public class WildAssemblyTreeResolver : AbstractAssemblyTreeResolver<WildAssemblyResolvedPatterns> {

	public WildAssemblyTreeResolver(
			AbstractAssemblyResolutionFactory<WildAssemblyResolvedPatterns,object> factory,
			SleighLanguage lang, Address at, AssemblyParseBranch tree, AssemblyPatternBlock context,
			AssemblyContextGraph ctxGraph) : base(factory, lang, at, tree, context, ctxGraph)
    {
	}

	protected AbstractAssemblyStateGenerator<object> getWildHiddenStateGenerator(OperandSymbol opSym,
			string wildcard, AssemblyResolvedPatterns fromLeft) {
		TripleSymbol defSym = opSym.getDefiningSymbol();
		if (defSym is SubtableSymbol subtable) {
			return new WildAssemblyConstructStateGenerator(this, subtable, wildcard, fromLeft);
		}
		return new WildAssemblyNopStateGenerator(this, null, opSym, wildcard, fromLeft);
	}

	/* @Override */
	protected AbstractAssemblyStateGenerator<object> getStateGenerator(OperandSymbol opSym,
			AssemblyParseTreeNode node, AssemblyResolvedPatterns fromLeft) {
		if (node is WildAssemblyParseHiddenNode hidden) {
			return getWildHiddenStateGenerator(opSym, hidden.wildcard, fromLeft);
		}
		if (node is AssemblyParseBranch branch && !branch.isConstructor()) {
			if (branch.getProduction() is WildAssemblyProduction) {
				System.Diagnostics.Debug.Assert(branch.getSubstitutions().size() == 1);
				return getStateGenerator(opSym, branch.getSubstitution(0), fromLeft);
			}
		}
		if (!(node is WildAssemblyParseToken token)) {
			return base.getStateGenerator(opSym, node, fromLeft);
		}
		if (node.getSym() is WildAssemblySubtableTerminal term) {
			return getWildHiddenStateGenerator(opSym, token.wildcardName(), fromLeft);
		}
		if (node.getSym() is WildAssemblyNumericMapTerminal term) {
			return new WildAssemblyNumericMapStateGenerator(this, token, opSym, term.map, fromLeft);
		}
		if (node.getSym() is WildAssemblyStringMapTerminal term) {
			return new WildAssemblyStringMapStateGenerator(this, token, opSym, term.map, fromLeft);
		}
		if (node.getSym() is WildAssemblyStringTerminal term) {
			return new WildAssemblyStringStateGenerator(this, token, opSym, term.str, fromLeft);
		}
		if (node.getSym() is WildAssemblyFixedNumericTerminal term) {
			return new WildAssemblyFixedNumericStateGenerator(this, token, opSym, term.val,
				fromLeft);
		}
		if (node.getSym() is WildAssemblyNumericTerminal term) {
			return new WildAssemblyNumericStateGenerator(this, token, opSym, token.wildcardName(),
				fromLeft);
		}
		return base.getStateGenerator(opSym, node, fromLeft);
	}
}
